function visibleCharacterCount(value) {
  return String(value || '').replace(/\s/g, '').length;
}

function buildLongformProject({ parentPath, projectService, name = '潮汐档案' }) {
  if (!projectService || typeof projectService.createProjectAt !== 'function' ||
      typeof projectService.atomicWriteFile !== 'function' || typeof projectService.createMarkdownFile !== 'function') {
    throw new TypeError('fixture builder requires the real ProjectService creation and revision APIs');
  }
  const descriptor = projectService.createProjectAt(parentPath, name);
  const rootPath = descriptor.rootPath;
  const initialEdit = projectService.readFileWithRevision(rootPath, 'edit.md');
  projectService.atomicWriteFile(rootPath, 'edit.md', EDIT_CONTENT, initialEdit.revision);
  fs.mkdirSync(path.join(rootPath, 'chapters'));
  fs.mkdirSync(path.join(rootPath, 'references'));
  for (const chapter of CHAPTERS) projectService.createMarkdownFile(rootPath, chapter.path, chapter.content);
  for (const source of SOURCES) projectService.createMarkdownFile(rootPath, source.path, source.content);

  const manuscriptCharacters = CHAPTERS.reduce((total, chapter) => total + visibleCharacterCount(chapter.content), 0);
  return Object.freeze({
    descriptor,
    rootPath,
    editPath: 'edit.md',
    chapterPaths: Object.freeze(CHAPTERS.map(chapter => chapter.path)),
    sourcePaths: Object.freeze(SOURCES.map(source => source.path)),
    manuscriptCharacters,
    allPublicPaths: Object.freeze(['edit.md', ...CHAPTERS.map(chapter => chapter.path), ...SOURCES.map(source => source.path)]),
  });
}

module.exports = {
  EDIT_CONTENT,
  CHAPTERS,
  SOURCES,
  visibleCharacterCount,
  buildLongformProject,
};
